public class ProductionFibonacci {  
 public static BigInteger getLargeFibonacci(int n) {  
 BigInteger a = BigInteger.ZERO;  
 BigInteger b = BigInteger.ONE;  

 for (int i = 1; i <= n; i++) {  
 BigInteger next = a.add(b);  
 a = b;  
 b = next;  
 }  
 return a;  
 }  
